15	const containsSphinx = (army: Card[]): boolean =>
16	  army.some((card) => card.monster === SPHINX);
17	
18	// A card's type is its monster; rank marks a variant (e.g. Undead Warrior
19	// (1) and (3)) and does not make it a separate type.
20	const typeOf = (card: Card): string => card.monster;
21	
22	const countDistinctTypes = (army: Card[]): number =>
23	  new Set(army.map(typeOf)).size;
24	
25	const pointsForTypeCount = (typeCount: number): number =>
26	  typeCount > BONUS_TYPE_THRESHOLD
27	    ? POINTS_PER_EXTRA_TYPE * (typeCount - BONUS_TYPE_THRESHOLD)
28	    : FEW_TYPES_POINTS;
29	
30	export const scoreArmy = (army: Card[]): number => {
31	  if (!containsSphinx(army)) return NO_SPHINX_SCORE;
32	  return SPHINX_BASE_POINTS + pointsForTypeCount(countDistinctTypes(army));
33	};
