const SPHINX_BASE_POINTS = 1;

// Variety points: a flat 1 up to and including four types, then 2 per type
// above four (so five types score 2, six types score 4).
const FLAT_VARIETY_POINTS = 1;
const VARIETY_POINTS_PER_TYPE_ABOVE = 2;
const TYPES_BEFORE_VARIETY_SCALES = 4;

