const pointsForTypeCount = (typeCount: number): number =>
  typeCount > BONUS_TYPE_THRESHOLD
    ? POINTS_PER_EXTRA_TYPE * (typeCount - BONUS_TYPE_THRESHOLD)
    : FEW_TYPES_POINTS;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return NO_SPHINX_SCORE;
  return SPHINX_BASE_POINTS + pointsForTypeCount(countDistinctTypes(army));
};

